record.field:
{
  "version": 1,
  "blocks": [
    {
      "id": "t_cls_1",
      "type": "company_header",
      "settings": {
        "show_logo": true,
        "show_company_name": true,
        "show_company_address": true,
        "logo_position": "left"
      }
    },
    {
      "id": "t_cls_2",
      "type": "separator",
      "settings": {"style": "solid", "color": "#000000", "margin": "10"}
    },
    {
      "id": "t_cls_3",
      "type": "partner_address",
      "settings": {"use_shipping": false, "show_vat": true}
    },
    {
      "id": "t_cls_4",
      "type": "document_title",
      "settings": {"font_size": "20", "bold": true, "alignment": "left"}
    },
    {
      "id": "t_cls_5",
      "type": "info_table",
      "settings": {"font_size": "10", "show_date": true, "show_number": true, "show_reference": true, "show_payment_term": true, "show_salesperson": false, "show_customer_number": false, "columns": 2}
    },
    {
      "id": "t_cls_6",
      "type": "line_items",
      "settings": {"show_product": true, "show_description": true, "show_quantity": true, "show_uom": true, "show_price_unit": true, "show_discount": true, "show_taxes": false, "show_subtotal": true}
    },
    {
      "id": "t_cls_7",
      "type": "subtotals",
      "settings": {"show_tax_details": true, "alignment": "right"}
    },
    {
      "id": "t_cls_8",
      "type": "notes",
      "settings": {"show_payment_terms": true, "show_notes": true}
    }
  ]
}

